  // 🎨 drawn pictures (wd-13): WisArt1…N.html arrive in the background after the page opens → addArt({cardId: '<svg…>'}); until then the emoji shows
  const ART = {};
  function addArt(m){ for(const k in (m || {})) if(typeof m[k] === 'string' && /^<svg/.test(m[k])) { ART[k] = m[k]; delete PIC_MEMO['art:' + k]; } }
  function hasArt(cd){ return !!(cd && ART[cd.id]); }
  function picUri(cd){
    if(ART[cd.id]){ const ka = 'art:' + cd.id; return PIC_MEMO[ka] || (PIC_MEMO[ka] = svgUri(ART[cd.id])); }
    const c = CAT[cd.cat], key = c.pic + ':' + cd.id;
    if(PIC_MEMO[key]) return PIC_MEMO[key];
    let svg = '';
    if(c.pic === 'shape') svg = shapeSvg(cd.pic, cd.color);
    else if(c.pic === 'map') svg = mapSvg(cd.pic);
    else if(c.pic === 'dino') svg = dinoSvg(cd.pic, cd.en);
    else if(c.pic === 'geo') svg = geoSvg(cd.pic);
    else if(c.pic === 'clock') svg = clockSvg(cd.pic);
    else if(c.pic === 'tune') svg = TUNE_SVG[cd.pic] || '';
    return (PIC_MEMO[key] = svg ? svgUri(svg) : '');
  }
