    if(c.pic === 'flag') return '<span class="wc-pic wc-flag ' + cls + '">' + flag(cd.pic) + '</span>';
    if(c.pic === 'capital') return '<span class="wc-pic wc-cap ' + cls + '"><span class="wc-flag">' + flag(cd.pic) + '</span><span class="wc-city">🏙️</span></span>';
    if(c.pic === 'formula') return '<span class="wc-pic wc-formula ' + cls + '" style="--len:' + [...cd.pic].length + '">' + cd.pic + '</span>';
    if(ART[cd.id]) return '<img class="wc-pic wc-img wc-art ' + cls + '" alt="" draggable="false" src="' + picUri(cd) + '">';
    if(c.pic === 'shape' || c.pic === 'map' || c.pic === 'dino' || c.pic === 'geo' || c.pic === 'tune' || isClock(cd)) return '<img class="wc-pic wc-img wc-' + c.pic + ' ' + cls + '" alt="" draggable="false" src="' + picUri(cd) + '">';
